<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class CandidateCvAnalysisController extends Controller{public function show(Request $request):JsonResponse{abort_unless($request->user()->account_type==='candidate',403);$p=$request->user()->candidateProfile;$score=0;$strengths=[];$improvements=[];$check=function(bool $ok,int $points,string $good,string $bad)use(&$score,&$strengths,&$improvements){if($ok){$score+=$points;$strengths[]=$good;}else{$improvements[]=$bad;}};$check(filled($p?->professional_title),10,'Tu titular profesional define claramente tu perfil.','Agrega un titular específico con el puesto o especialidad que buscas.');$summary=trim((string)$p?->summary);$check(mb_strlen($summary)>=120,15,'Tu resumen tiene suficiente contexto profesional.','Amplía el resumen a 3-5 líneas: experiencia, especialidad y valor que aportas.');$experience=$p?->experience??[];$check(count($experience)>0,20,'Incluiste experiencia profesional.','Agrega al menos una experiencia, práctica, proyecto o trabajo independiente.');$descriptions=collect($experience)->pluck('description')->filter()->implode(' ');$check((bool)preg_match('/\d|%|RD\$|US\$/u',$descriptions),10,'Tus logros incluyen resultados medibles.','Convierte tareas en logros con cifras, porcentajes, tiempo o impacto.');$check(count($p?->education??[])>0,10,'Tu formación académica está incluida.','Incluye tu formación, cursos técnicos o estudios relevantes.');$check(count($p?->skills??[])>=5,10,'Tienes una buena base de habilidades relevantes.','Incluye entre 5 y 12 habilidades relacionadas con el puesto objetivo.');$check(count($p?->languages??[])>0,5,'Indicaste los idiomas que manejas.','Añade tus idiomas y nivel de dominio.');$check(filled($p?->portfolio_url),5,'Incluiste un enlace profesional o portafolio.','Añade LinkedIn, GitHub o un portafolio profesional.');$check(filled($request->user()->phone),5,'Tus datos de contacto están completos.','Agrega un teléfono de contacto a tu cuenta.');$check(count($p?->certifications??[])>0,5,'Incluiste certificaciones relevantes.','Si tienes cursos o certificaciones, añádelos para reforzar tu perfil.');$check((bool)$p?->photo_path,5,'Tienes fotografía disponible para plantillas visuales.','Añade una foto profesional si usarás una plantilla con fotografía.');$level=$score>=85?'Excelente':($score>=70?'Muy bueno':($score>=50?'En progreso':'Necesita atención'));return response()->json(['data'=>['score'=>$score,'level'=>$level,'strengths'=>array_slice($strengths,0,6),'improvements'=>array_slice($improvements,0,6),'summary'=>$score>=85?'Tu CV está listo para competir. Adáptalo a cada vacante antes de enviarlo.':($score>=70?'Tu CV tiene una base sólida; completa las recomendaciones para aumentar su impacto.':'Completa primero las mejoras prioritarias para presentar mejor tu experiencia.')]]);}}
